namespace MeteoStanice.Data.Entities;

/// <summary>
/// Registered physical meteo station.
/// </summary>
public sealed class Station
{
    /// <summary>
    /// Database identifier.
    /// </summary>
    public Guid Id { get; set; } = Guid.NewGuid();

    /// <summary>
    /// Stable station GUID generated by firmware.
    /// </summary>
    public Guid StationGuid { get; set; }

    /// <summary>
    /// Human readable station code.
    /// </summary>
    public string StationCode { get; set; } = string.Empty;

    /// <summary>
    /// Station display name.
    /// </summary>
    public string Name { get; set; } = string.Empty;

    /// <summary>
    /// Manually configured station location.
    /// </summary>
    public string LocationText { get; set; } = string.Empty;

    /// <summary>
    /// Hardware identifier reported by firmware.
    /// </summary>
    public string HardwareId { get; set; } = string.Empty;

    /// <summary>
    /// Firmware version reported by station.
    /// </summary>
    public string FirmwareVersion { get; set; } = string.Empty;

    /// <summary>
    /// UTC timestamp when the station was created in the backend.
    /// </summary>
    public DateTimeOffset CreatedAt { get; set; }

    /// <summary>
    /// UTC timestamp of the last accepted measurement or event.
    /// </summary>
    public DateTimeOffset? LastSeenAt { get; set; }

    /// <summary>
    /// True when station is active.
    /// </summary>
    public bool IsActive { get; set; } = true;

    /// <summary>
    /// Measurements produced by the station.
    /// </summary>
    public ICollection<Measurement> Measurements { get; set; } = new List<Measurement>();
}
